parameters.jsCode:
const data = $input.first().json;

if (!Array.isArray(data.intermediateSteps)) {
  throw new Error('V AI Agent zapni Return Intermediate Steps.');
}

function parseResult(value) {
  if (typeof value !== 'string') return value ?? null;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

const steps = data.intermediateSteps.map((step, index) => ({
  step: index + 1,
  tool: step.action.tool,
  input: step.action.toolInput,
  result: parseResult(step.observation),
}));

const errors = steps.flatMap(step => {
  const results = Array.isArray(step.result)
    ? step.result
    : [step.result];

  return results
    .filter(result =>
      result &&
      typeof result === 'object' &&
      (result.status === 'error' || result.error_code)
    )
    .map(result => ({
      step: step.step,
      tool: step.tool,
      error_code: result.error_code || 'TOOL_ERROR',
      reason: result.reason || null,
    }));
});

return [{
  json: {
    request_id: $execution.id,
    environment: 'mock',
    summary: data.output,
    steps,
    errors,
  },
}];
